import csv
import json
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent
INPUT_FILE = BASE_DIR / 'data.csv'
OUTPUT_FILE = BASE_DIR / 'summary.json'


def parse_number(text):
    text = text.strip()
    try:
        return int(text)
    except ValueError:
        return float(text)


def read_values(path):
    with open(path, newline='') as handle:
        reader = csv.DictReader(handle)
        return [parse_number(row['value']) for row in reader if row.get('value')]


def summarize(values):
    average = sum(values) / len(values)
    if float(average).is_integer():
        average = int(average)
    return {'rows': len(values), 'average': average}


def main():
    values = read_values(INPUT_FILE)
    with open(OUTPUT_FILE, 'w') as handle:
        json.dump(summarize(values), handle, indent=2)
        handle.write('\n')


if __name__ == '__main__':
    main()

